/**
 * The pins for what the local narrator downloads, in the app's own bundle.
 *
 * `narratorPins.json` is generated by `scripts/stage-narrator-assets.mjs` from
 * the bytes it actually wrote, and the same JSON is served next to the assets
 * at `/voice/narrator/manifest.json` so anyone can check them independently.
 * `narratorAssets.test.ts` re-hashes every shipped file against these pins, so a
 * swapped or truncated asset fails the suite instead of shipping quietly.
 *
 * The consent copy reads the real first-download total from here rather than
 * advertising only the graph size, and it does so without fetching anything:
 * before the user's Enable gesture the app makes no request of its own.
 */
import pins from './narratorPins.json'

export interface PartPinsJson {
  path: string
  bytes: number
  sha256: string
}

export interface NarratorPins {
  component: string
  model: { provider: string; revision: string; licence: string; notice: string }
  graph: { name: string; bytes: number; sha256: string; parts: PartPinsJson[] }
  voice: {
    name: string; alias: string; key: string
    path: string; bytes: number; sha256: string
    dtype: string; byteOrder: string; shape: number[]; derivation: string
    derivedFrom: { name: string; bytes: number; sha256: string; shipped: boolean }
  }
  runtime: {
    component: string; version: string; licence: string; notice: string; choice: string
    bundle: PartPinsJson; glue: PartPinsJson; wasm: PartPinsJson
  }
  phonemizer: {
    manifest: string; component: string; project: string; tag: string; commit: string
    licence: string; modified: string; noticeIndex: string; notice: string
    source: { offer: string; file: string; bytes: number; sha256: string; files: number }
    adapter: { path: string; bytes: number }
    loader: { path: string; bytes: number }
    files: { role: string; path: string; bytes: number; sha256: string }[]
  }
  symbols: { path: string; bytes: number; sha256: string }
  perFileLimit: { host: string; bytes: number }
  transfer: { bytes: number; entries: { path: string; bytes: number; why: string }[] }
}

export const NARRATOR_PINS: NarratorPins = pins as NarratorPins

/** Everything the assets are served from, relative to the site root. */
export const NARRATOR_BASE_PATH = '/voice/narrator/'

/** Absolute URL for a path recorded in the manifest, which is relative to the manifest's directory. */
export function narratorPath(path: string, origin: string): string {
  return new URL(path, new URL(NARRATOR_BASE_PATH, origin)).href
}

/** The real first-download size for one opt-in, not just the graph. */
export const NARRATOR_TRANSFER_BYTES: number = NARRATOR_PINS.transfer.bytes

/** The largest single served file, for a per-file-limit claim. */
export const NARRATOR_LARGEST_FILE: number = Math.max(...NARRATOR_PINS.transfer.entries.map(entry => entry.bytes))
